package main

func letterCount(name string) int {
	n := 0
	for range name {
		n++
	}
	return n
}

func letterIndex(name string, letter rune) int {
	n := 0
	for _, r := range name {
		if r == letter {
			return n
		}
		n++
	}
	return -1
}

