question.answer:
package main

import "strings"

func spaced(word string) string {
	var b strings.Builder
	for i, r := range word {
		if i > 0 {
			b.WriteByte(' ')
		}
		b.WriteRune(r)
	}
	return b.String()
}

func underlined(word string) string {
	var b strings.Builder
	b.WriteString(word)
	b.WriteByte('\n')
	for range word {
		b.WriteByte('-')
	}
	return b.String()
}

func marquee(word string, copies int) (string, int) {
	var b strings.Builder
	for i := 0; i < copies; i++ {
		if i > 0 {
			b.WriteString(" * ")
		}
		b.WriteString(word)
	}
	return b.String(), b.Len()
}
